import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/gestures.dart';
import 'package:flutter/material.dart';

import 'config.dart';
import 'firebase_options.dart';
import 'screens/auth_gate.dart';
import 'services.dart';
import 'theme.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  // lib/firebase_options.dart is generated by `flutterfire configure` and
  // holds the Android, iOS and web configs; currentPlatform picks the right one.
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);
  runApp(Services(child: const PerpsLeagueApp()));
}

/// Lets mouse and trackpad users drag lists, so pull-to-refresh works in the
/// browser and on desktop as well as on phones.
class _AppScrollBehavior extends MaterialScrollBehavior {
  const _AppScrollBehavior();

  @override
  Set<PointerDeviceKind> get dragDevices => const {
        PointerDeviceKind.touch,
        PointerDeviceKind.mouse,
        PointerDeviceKind.trackpad,
        PointerDeviceKind.stylus,
      };
}

class PerpsLeagueApp extends StatelessWidget {
  const PerpsLeagueApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: AppConfig.appName,
      debugShowCheckedModeBanner: false,
      theme: buildTheme(),
      darkTheme: buildTheme(),
      themeMode: ThemeMode.dark,
      scrollBehavior: const _AppScrollBehavior(),
      home: const AuthGate(),
    );
  }
}
